function checkPassword(password: string): string[] {
    const rules: [RegExp, string][] = [
        [/.{8,}/, "kamida 8 belgi"],
        [/[a-z]/, "kichik harf"],
        [/[A-Z]/, "katta harf"],
        [/\d/, "raqam"],
        [/[^A-Za-z0-9]/, "maxsus belgi"],
    ]
    return rules.filter(([pattern]) => !pattern.test(password)).map(([, message]) => message)
}

for (const p of ["abc", "Parol123", "Parol123!"]) {
    const missing = checkPassword(p)
    console.log(`"${p}": ${missing.length === 0 ? "✓ kuchli" : "yetishmaydi — " + missing.join(", ")}`)
}

